'use strict';

/**
 * API Gateway (lambda-proxy) response helpers.
 * CORS origin is "*" for now; see the project notes before tightening it.
 */

const CORS_HEADERS = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'Content-Type,Authorization,Idempotency-Key',
};

function json(statusCode, body, headers) {
    return {
        statusCode,
        headers: { 'Content-Type': 'application/json', ...CORS_HEADERS, ...(headers || {}) },
        body: JSON.stringify(body),
    };
}

function noContent(headers) {
    return { statusCode: 204, headers: { ...CORS_HEADERS, ...(headers || {}) }, body: '' };
}

module.exports = {
    CORS_HEADERS,
    json,
    noContent,
    ok: (body, headers) => json(200, body, headers),
    created: (body, headers) => json(201, body, headers),
    badRequest: (message, details) => json(400, { error: 'BadRequest', message, ...(details ? { details } : {}) }),
    notFound: (message) => json(404, { error: 'NotFound', message: message || 'Not found' }),
    serverError: () => json(500, { error: 'InternalServerError', message: 'Something went wrong' }),
};
